  id: "S05-16", module: "D", topic: "A rotating sphere: how latitude changes the centripetal acceleration", diff: 3, rel: [["D", "A point at latitude lambda moves in a circle of radius r cos lambda about the spin axis"], ["D", "Centripetal acceleration is omega^2 times that circular radius"], ["A", "Forming the ratio of the acceleration at latitude to that at the equator"]], key: ["latitude", "centripetal", "rotationaxis"], ans: 4, paper: "BANK-S05",
